      async load() { await fetchValue(); return <p>Loaded slot {count}</p>; },
      *steps() { yield <p>First slot {enabled && <Choice branch={mode} one={<b>Owned {account.name}</b>} other={fallback} />}</p>; return <p>Last slot</p>; },
    }}><section>Visible body {count}</section></Card>);
    };

